"""Generate the reviewable CloudFormation JSON. No AWS calls or secrets."""
import json
from pathlib import Path
R=lambda name:{'Ref':name}
A=lambda name,attr:{'Fn::GetAtt':[name,attr]}
S=lambda value:{'Fn::Sub':value}
I=lambda condition,yes,no:{'Fn::If':[condition,yes,no]}
common=[{'Key':'Project','Value':'Further'},{'Key':'Environment','Value':R('Environment')},{'Key':'ManagedBy','Value':'CloudFormation'},{'Key':'created_by','Value':'aurora-skill'},{'Key':'generation_model','Value':'unknown'}]
def resource(kind,properties,retain=False,condition=None):
 value={'Type':kind,'Properties':properties}
 if retain:value.update(DeletionPolicy='Retain',UpdateReplacePolicy='Retain')
 if condition:value['Condition']=condition
 return value
params={
'Environment':{'Type':'String','Default':'dev','AllowedValues':['dev'],'Description':'Isolated Further development environment.'},
'DatabaseName':{'Type':'String','Default':'further','AllowedPattern':'[a-z][a-z0-9]{0,62}','Description':'Initial PostgreSQL application database.'},
'DatabaseEngineVersion':{'Type':'String','Default':'17.9','AllowedPattern':'[0-9]+\\.[0-9]+','Description':'Verified Aurora PostgreSQL version supporting Data API and zero-ACU pause.'},
'MaxDatabaseCapacity':{'Type':'Number','Default':2,'MinValue':1,'MaxValue':32,'Description':'Bounded development ceiling in ACUs, not a workload capacity forecast.'},
'FacebookAppId':{'Type':'String','Default':'','AllowedPattern':'^$|^[0-9]+$','Description':'Optional Facebook Login app ID. Leave blank until app setup is complete.'},
'FacebookApiVersion':{'Type':'String','Default':'v21.0','AllowedPattern':r'^v[1-9][0-9]*\.[0-9]+$','Description':'Explicit federation version; v21.0 was the highest offered by Cognito us-east-1 on November 2, 2026. Recheck Cognito support and Meta lifecycle before upgrading.'},
'FacebookSecretArn':{'Type':'String','Default':'','AllowedPattern':'^$|^arn:aws:secretsmanager:[a-z0-9-]+:[0-9]{12}:secret:.+$','Description':'Optional same-region Secrets Manager ARN holding JSON key app_secret. No secret value in parameters.'}}
conditions={'HasFacebook':{'Fn::And':[{'Fn::Not':[{'Fn::Equals':[R('FacebookAppId'),'']}]},{'Fn::Not':[{'Fn::Equals':[R('FacebookSecretArn'),'']}]}]}}
resources={
'Vpc':resource('AWS::EC2::VPC',{'CidrBlock':'10.88.0.0/24','EnableDnsSupport':True,'EnableDnsHostnames':True,'Tags':common}),
'PrivateSubnetA':resource('AWS::EC2::Subnet',{'VpcId':R('Vpc'),'CidrBlock':'10.88.0.0/26','AvailabilityZone':{'Fn::Select':[0,{'Fn::GetAZs':''}]},'MapPublicIpOnLaunch':False,'Tags':common}),
'PrivateSubnetB':resource('AWS::EC2::Subnet',{'VpcId':R('Vpc'),'CidrBlock':'10.88.0.64/26','AvailabilityZone':{'Fn::Select':[1,{'Fn::GetAZs':''}]},'MapPublicIpOnLaunch':False,'Tags':common}),
'DatabaseSecurityGroup':resource('AWS::EC2::SecurityGroup',{'GroupDescription':'Further private database. No inbound PostgreSQL; application uses authenticated Data API.','VpcId':R('Vpc'),'SecurityGroupIngress':[],'SecurityGroupEgress':[{'IpProtocol':'-1','CidrIp':'10.88.0.0/24','Description':'Private VPC traffic only; no internet route is provisioned.'}],'Tags':common}),
'DatabaseSubnetGroup':resource('AWS::RDS::DBSubnetGroup',{'DBSubnetGroupDescription':'Further private Aurora subnets in two availability zones.','SubnetIds':[R('PrivateSubnetA'),R('PrivateSubnetB')],'Tags':common}),
'DatabaseCluster':resource('AWS::RDS::DBCluster',{'Engine':'aurora-postgresql','EngineMode':'provisioned','EngineVersion':R('DatabaseEngineVersion'),'DatabaseName':R('DatabaseName'),'MasterUsername':'further_admin','ManageMasterUserPassword':True,'StorageEncrypted':True,'BackupRetentionPeriod':7,'CopyTagsToSnapshot':True,'DeletionProtection':True,'EnableHttpEndpoint':True,'DBSubnetGroupName':R('DatabaseSubnetGroup'),'VpcSecurityGroupIds':[R('DatabaseSecurityGroup')],'Port':5432,'ServerlessV2ScalingConfiguration':{'MinCapacity':0,'MaxCapacity':R('MaxDatabaseCapacity'),'SecondsUntilAutoPause':300},'Tags':common},retain=True),
'DatabaseWriter':resource('AWS::RDS::DBInstance',{'DBClusterIdentifier':R('DatabaseCluster'),'Engine':'aurora-postgresql','DBInstanceClass':'db.serverless','PubliclyAccessible':False,'AutoMinorVersionUpgrade':True,'MonitoringInterval':0,'Tags':common},retain=True),
'UserPool':resource('AWS::Cognito::UserPool',{'UserPoolName':S('${AWS::StackName}-users'),'UserPoolTier':'LITE','DeletionProtection':'ACTIVE','UsernameAttributes':['email'],'UsernameConfiguration':{'CaseSensitive':False},'AutoVerifiedAttributes':['email'],'AdminCreateUserConfig':{'AllowAdminCreateUserOnly':False},'AccountRecoverySetting':{'RecoveryMechanisms':[{'Name':'verified_email','Priority':1}]},'UserAttributeUpdateSettings':{'AttributesRequireVerificationBeforeUpdate':['email']},'MfaConfiguration':'OFF','Policies':{'PasswordPolicy':{'MinimumLength':12,'RequireLowercase':True,'RequireUppercase':True,'RequireNumbers':True,'RequireSymbols':False,'TemporaryPasswordValidityDays':7}},'EmailConfiguration':{'EmailSendingAccount':'COGNITO_DEFAULT'},'VerificationMessageTemplate':{'DefaultEmailOption':'CONFIRM_WITH_CODE'},'Schema':[{'Name':'email','AttributeDataType':'String','Mutable':True,'Required':True},{'Name':'name','AttributeDataType':'String','Mutable':True,'Required':True},{'Name':'preferred_username','AttributeDataType':'String','Mutable':True,'Required':False}],'UserPoolTags':{'Project':'Further','Environment':R('Environment'),'ManagedBy':'CloudFormation'}},retain=True),
'FacebookIdentityProvider':resource('AWS::Cognito::UserPoolIdentityProvider',{'UserPoolId':R('UserPool'),'ProviderName':'Facebook','ProviderType':'Facebook','ProviderDetails':{'client_id':R('FacebookAppId'),'client_secret':S('{{resolve:secretsmanager:${FacebookSecretArn}:SecretString:app_secret}}'),'authorize_scopes':'public_profile,email','api_version':R('FacebookApiVersion')},'AttributeMapping':{'email':'email','name':'name'}},condition='HasFacebook'),
'UserPoolClient':resource('AWS::Cognito::UserPoolClient',{'ClientName':S('${AWS::StackName}-local-ui'),'UserPoolId':R('UserPool'),'GenerateSecret':False,'PreventUserExistenceErrors':'ENABLED','EnableTokenRevocation':True,'ExplicitAuthFlows':['ALLOW_USER_PASSWORD_AUTH','ALLOW_REFRESH_TOKEN_AUTH'],'AllowedOAuthFlowsUserPoolClient':True,'AllowedOAuthFlows':['code'],'AllowedOAuthScopes':['openid','email','profile'],'SupportedIdentityProviders':I('HasFacebook',['COGNITO',R('FacebookIdentityProvider')],['COGNITO']),'CallbackURLs':['http://localhost:3000/api/auth/cognito/callback','http://127.0.0.1:3000/api/auth/cognito/callback'],'DefaultRedirectURI':'http://localhost:3000/api/auth/cognito/callback','LogoutURLs':['http://localhost:3000/','http://127.0.0.1:3000/','http://localhost:3000/login','http://127.0.0.1:3000/login'],'ReadAttributes':['email','email_verified','name','preferred_username'],'WriteAttributes':['email','name','preferred_username'],'RefreshTokenValidity':7,'AccessTokenValidity':60,'IdTokenValidity':60,'TokenValidityUnits':{'AccessToken':'minutes','IdToken':'minutes','RefreshToken':'days'}},retain=True),
'UserPoolDomain':resource('AWS::Cognito::UserPoolDomain',{'Domain':S('${AWS::StackName}-${AWS::AccountId}'),'UserPoolId':R('UserPool'),'ManagedLoginVersion':1},retain=True),
'MediaBucket':resource('AWS::S3::Bucket',{'PublicAccessBlockConfiguration':{'BlockPublicAcls':True,'BlockPublicPolicy':True,'IgnorePublicAcls':True,'RestrictPublicBuckets':True},'BucketEncryption':{'ServerSideEncryptionConfiguration':[{'ServerSideEncryptionByDefault':{'SSEAlgorithm':'AES256'}}]},'OwnershipControls':{'Rules':[{'ObjectOwnership':'BucketOwnerEnforced'}]},'VersioningConfiguration':{'Status':'Enabled'},'Tags':common},retain=True),
'MediaBucketPolicy':resource('AWS::S3::BucketPolicy',{'Bucket':R('MediaBucket'),'PolicyDocument':{'Version':'2012-10-17','Statement':[{'Sid':'DenyInsecureTransport','Effect':'Deny','Principal':'*','Action':'s3:*','Resource':[A('MediaBucket','Arn'),S('${MediaBucket.Arn}/*')],'Condition':{'Bool':{'aws:SecureTransport':'false'}}}]}},retain=True),
'LocalDeveloperPolicy':resource('AWS::IAM::ManagedPolicy',{'Description':'Further development backend access only. Unattached; does not grant access to any person automatically.','PolicyDocument':{'Version':'2012-10-17','Statement':[{'Sid':'ApplicationDatabase','Effect':'Allow','Action':['rds-data:ExecuteStatement','rds-data:BatchExecuteStatement','rds-data:BeginTransaction','rds-data:CommitTransaction','rds-data:RollbackTransaction'],'Resource':A('DatabaseCluster','DBClusterArn')},{'Sid':'DatabaseCredentialReference','Effect':'Allow','Action':['secretsmanager:GetSecretValue'],'Resource':A('DatabaseCluster','MasterUserSecret.SecretArn')},{'Sid':'ListApplicationMedia','Effect':'Allow','Action':['s3:ListBucket'],'Resource':A('MediaBucket','Arn')},{'Sid':'ReadWriteApplicationMedia','Effect':'Allow','Action':['s3:GetObject','s3:PutObject'],'Resource':S('${MediaBucket.Arn}/*')}]}})}
outputs={
'AwsRegion':{'Description':'Region for local SDK clients.','Value':R('AWS::Region')},
'DatabaseClusterArn':{'Description':'Aurora cluster ARN for Data API calls.','Value':A('DatabaseCluster','DBClusterArn')},
'DatabaseSecretArn':{'Description':'RDS-managed secret ARN reference; no password output.','Value':A('DatabaseCluster','MasterUserSecret.SecretArn')},
'DatabaseName':{'Description':'Application database for migrations and queries.','Value':R('DatabaseName')},
'DatabaseClusterIdentifier':{'Description':'Private Aurora cluster identifier for operational inspection.','Value':R('DatabaseCluster')},
'UserPoolId':{'Description':'Cognito user pool for manual and optional social sign-in.','Value':R('UserPool')},
'UserPoolClientId':{'Description':'Public app client; it has no client secret.','Value':R('UserPoolClient')},
'CognitoDomain':{'Description':'Cognito classic hosted login origin (Lite tier).','Value':S('https://${UserPoolDomain}.auth.${AWS::Region}.amazoncognito.com')},
'CognitoIssuer':{'Description':'Expected JWT issuer.','Value':S('https://cognito-idp.${AWS::Region}.amazonaws.com/${UserPool}')},
'MediaBucketName':{'Description':'Private application media bucket.','Value':R('MediaBucket')},
'LocalDeveloperPolicyArn':{'Description':'Unattached least-privilege application access policy for a future developer role.','Value':R('LocalDeveloperPolicy')},
'FacebookConfigured':{'Description':'True only when the real Facebook app provider is included.','Value':I('HasFacebook','true','false')}}
template={'AWSTemplateFormatVersion':'2010-09-09','Description':'Further development data and identity: private Aurora PostgreSQL serverless with Data API, Cognito Lite, and private media. APIs and Meta agents stay local.','Metadata':{'Purpose':'Development environment. Capacity cap is a spending guardrail, not a measured sizing recommendation.','Connection':'Local backend uses temporary AWS credentials and Data API. No database ingress, NAT gateway, public database endpoint or application hosting is created.'},'Parameters':params,'Conditions':conditions,'Resources':resources,'Outputs':outputs}
path=Path(__file__).with_name('further-dev.json');path.write_text(json.dumps(template,indent=2)+'\n');print(f'{path}: {len(resources)} resources, {path.stat().st_size} bytes')
